insert into public.recipes(slug,country_code,title,description,cuisine_note,total_minutes,base_servings,allergens,substitutions) values ('ginger-chicken','SG','Ginger chicken & brown rice','Ginger-and-soy chicken with brown rice, broccoli, carrots, fresh cucumber, spring onion and lime. A Singapore-inspired meal-prep bowl; choose pan or air fryer for the same seasoned chicken.','Cuisine-inspired healthycooks draft; not kitchen-tested.',55,2,array['Soy; wheat if your soy sauce contains it.'],'Replace chicken with firm tofu if preferred; recalculate nutrition and check the tofu label. Use tamari labelled gluten-free if needed.');
