insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=LzsSQmbALSo','How to cook brown rice','Learn To Cook / Chef Mark','Third-party platform embed; no download or editing permission obtained.','https://learntocook.com/rice/how-to-cook-brown-rice/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),0,'Start the brown rice','Rinse, add water, then cover and simmer according to your rice packet.','Measure the rice and follow its packet water ratio and cooking time. Once simmering, cover and lower the heat. Use the timer as a reminder and adjust it to the packet. Continue with the ingredient prep while it cooks.','Tender grains with no hard centre. The demo uses its own rice ratio; follow your packet for yours.',2700,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=LzsSQmbALSo'),0,null,'stovetop');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='ginger-chicken') and position=0),(select id from public.recipes where slug='ginger-chicken'),'stovetop','Stovetop','Measure the rice and follow its packet water ratio and cooking time. Once simmering, cover and lower the heat. Use the timer as a reminder and adjust it to the packet. Continue with the ingredient prep while it cooks.','Rinse, add water, then cover and simmer according to your rice packet.','Tender grains with no hard centre. The demo uses its own rice ratio; follow your packet for yours.',2700,null,'{"hint":"Use the packet timing","facts":[["Heat","Gentle simmer"],["Time","Follow your rice packet"]],"checklist":["Start the measured rice using your packet’s water ratio and time.","Leave it cooking while you prepare the vegetables, aromatics and chicken."],"adjustableTimer":true,"timerLabel":"Rice reminder"}'::jsonb,'https://learntocook.com/rice/how-to-cook-brown-rice/',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=LzsSQmbALSo'));
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='ginger-chicken') and position=0),(select id from public.recipes where slug='ginger-chicken'),'rice-cooker','Rice cooker','Measure the dry rice with your cooker’s own cup to find its volume; the ingredient list still gives the amount by weight. Use the brown-rice water markings appropriate to that amount and rice type, following your model’s manual. Do not use white-rice markings automatically. Check minimum and maximum batch sizes: a small portion may be below your cooker’s minimum. If it has no Brown Rice setting, use the manufacturer’s specific brown-rice directions. Let the complete cycle and any instructed rest finish, then fluff. Start the vegetable and chicken prep while it cooks. The appliance controls temperature and cooking duration; hands-off does not always mean faster.','Rinse the rice, add water using your cooker’s brown-rice instructions, select Brown Rice and start.','The cooker has finished its full cycle and any instructed rest. Grains should be tender through the centre.',0,null,'{"hint":"Hands-off cooking","facts":[["Setting","Brown Rice"],["Temperature","Automatic"],["Time","Your cooker’s full cycle"]],"checklist":["Use the cooker’s own cup and brown-rice water guide; check its minimum batch size.","Select Brown Rice and complete the ingredient prep while it cooks.","Let the whole cycle and any instructed rest finish, then fluff."],"methodNote":"There is no universal rice-cooker temperature or countdown. The full meal can take longer than the 55-minute stovetop estimate.","adjustableTimer":false,"timerLabel":"Rice reminder","mediaGap":"A matching rice-cooker video is still to be added. Zojirushi’s linked guide has step-by-step photographs; follow your own model’s manual for settings.","gapTitle":"Set the rice cooking"}'::jsonb,'https://zojirushi.sg/recipes/brown-rice/',null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=CRYQeHVkh8E','Prepare broccoli','Iowa State University Extension','Third-party platform embed; no download or editing permission obtained.','https://spendsmart.extension.iastate.edu/video/prepare-broccoli/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),1,'Prepare the vegetables','Cut all the vegetables and toppings now. Keep broccoli and carrots separate from the ingredients you will serve raw.','Wash the vegetables and lime. Cut broccoli into similar, roughly 3 cm florets. Peel the carrot if needed and cut into 3 mm slices or half-moons. Cut cucumber into half-moons, finely slice the spring onions and cut the lime into wedges. Set broccoli and carrots aside for step 7. Keep cucumber, spring onion and lime in a clean covered container in the fridge for the final step. Do this before handling raw chicken.','Evenly sized broccoli and thin carrots for cooking; cucumber, spring onion and lime ready for serving.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=CRYQeHVkh8E'),0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=v908vjRX8Gc','How to peel ginger','Jamie Oliver','Third-party platform embed; no download or editing permission obtained.','https://www.jamieoliver.com/inspiration/how-to-peel-ginger-jamie-s-1-minute-tips/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),2,'Peel & grate the ginger','Scrape off the ginger skin with a spoon, then finely grate it.','Steady the ginger on a board while peeling. Use a fine grater over a small bowl and keep your fingertips away from the teeth. Stop grating before the last small piece becomes difficult to hold.','Fine, moist ginger shreds, ready to mix into the chicken seasoning. The video demonstrates peeling only.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=v908vjRX8Gc'),0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=qjzTZiY1vmk','How to chop garlic','Jamie Oliver','Third-party platform embed; no download or editing permission obtained.','https://www.youtube.com/watch?v=qjzTZiY1vmk','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),3,'Finely chop the garlic','Peel the garlic cloves, then chop them into small pieces.','Keep fingertips tucked away from the blade and the board stable. Set the chopped garlic beside the grated ginger so both are ready before cooking starts.','Small garlic pieces, rather than thick slices.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=qjzTZiY1vmk'),0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=-l3TxkEldPs','How to cube chicken breast','Laura Fuentes','Third-party platform embed; no download or editing permission obtained.','https://www.laurafuentes.com/cut-chicken-breasts/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),4,'Cut & season the chicken','Cut chicken into even 2.5 cm cubes. Mix with all the measured oil, ginger, garlic and soy sauce—once, for either cooking method.','Use a separate board for raw meat and do not wash raw chicken. Cut into strips and then roughly 2.5 cm cubes. In a bowl, combine all the measured oil, grated ginger and its juice, chopped garlic and reduced-salt soy sauce. Add the chicken and toss to coat. No marinating wait is required. Keep covered in the fridge if you are waiting for the rice. Wash hands, board, knife and surfaces afterwards. Use clean tongs and a clean plate for cooked chicken. Do not add a second set of these ingredients when you choose a cooking method.','Even chicken cubes lightly coated in ginger-and-soy seasoning. This is the same starting point for both cooking methods.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=-l3TxkEldPs'),30,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=TglLMjY316Y','Chicken with ginger & spring onion','Spice N’ Pans','Third-party platform embed; no download or editing permission obtained.','https://www.youtube.com/watch?v=TglLMjY316Y','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),5,'Cook the ginger chicken','Cook the already-seasoned chicken in a non-stick pan over medium heat, turning regularly. Start checking after 8 minutes.','Warm a non-stick frying pan over medium heat. Add the seasoned chicken from step 5 in one layer, along with its coating. Do not add the oil, ginger, garlic or soy again. Add the measured water to help stop the fine aromatics catching, and let it bubble gently. Turn the pieces regularly, lowering the heat or adding a small splash of water if the coating starts to scorch. Cook for about 8–12 minutes, longer if needed. Cut open several of the largest pieces with a clean knife: the centre should be steaming hot, with no pink meat and clear juices. If any check fails or you are unsure, cook longer and check again. Time and a browned outside alone do not prove it is cooked. Transfer cooked chicken and pan juices to a clean bowl. Lime and spring onion are added only at assembly.','Cut open several of the largest pieces with a clean knife: the centre should be steaming hot, with no pink meat and clear juices. If any check fails or you are unsure, cook longer and check again. Time and a browned outside alone do not prove it is cooked.',480,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=TglLMjY316Y'),0,null,'pan');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='ginger-chicken') and position=5),(select id from public.recipes where slug='ginger-chicken'),'pan','Pan','Warm a non-stick frying pan over medium heat. Add the seasoned chicken from step 5 in one layer, along with its coating. Do not add the oil, ginger, garlic or soy again. Add the measured water to help stop the fine aromatics catching, and let it bubble gently. Turn the pieces regularly, lowering the heat or adding a small splash of water if the coating starts to scorch. Cook for about 8–12 minutes, longer if needed. Cut open several of the largest pieces with a clean knife: the centre should be steaming hot, with no pink meat and clear juices. If any check fails or you are unsure, cook longer and check again. Time and a browned outside alone do not prove it is cooked. Transfer cooked chicken and pan juices to a clean bowl. Lime and spring onion are added only at assembly.','Cook the already-seasoned chicken in a non-stick pan over medium heat, turning regularly. Start checking after 8 minutes.','Cut open several of the largest pieces with a clean knife: the centre should be steaming hot, with no pink meat and clear juices. If any check fails or you are unsure, cook longer and check again. Time and a browned outside alone do not prove it is cooked.',480,null,'{"hint":"Stir-fry finish","facts":[["Heat","Medium"],["Cook","About 8–12 min"],["Start with","Seasoned chicken from step 5"]],"checklist":["Use the seasoned chicken from step 5. Do not season it a second time.","Cook in one layer; add the measured water and turn regularly. Keep the ginger and garlic from scorching.","Check the largest pieces from 8 minutes. Keep cooking until the centre passes all the checks below."],"methodNote":"Same ingredients and preparation as the air-fryer route. The pan leaves a little ginger-and-soy cooking juice; the air fryer gives a drier finish. This recipe still needs kitchen testing.","adjustableTimer":false,"timerLabel":"First chicken check at 8 minutes"}'::jsonb,'https://www.youtube.com/watch?v=TglLMjY316Y',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=TglLMjY316Y'));
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=B2co2uSknew','Air fryer chicken bites','Laura Fuentes','Third-party platform embed; no download or editing permission obtained.','https://www.laurafuentes.com/air-fryer-chicken-bites/','platform_embed','pending');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='ginger-chicken') and position=5),(select id from public.recipes where slug='ginger-chicken'),'air-fryer','Air fryer','Preheat the air fryer to 200°C for about 5 minutes, or follow its manual. Place the seasoned chicken from step 5 in one layer with space around the pieces. Do not add the oil, ginger, garlic or soy again. Leave excess liquid in the raw-chicken bowl and discard it; do not pour it over cooked food. Cook about 10–12 minutes per batch, shaking or turning after 5 minutes. Start checking at 10 minutes. Cut open several of the largest pieces with a clean knife: the centre should be steaming hot, with no pink meat and clear juices. If any check fails or you are unsure, cook longer and check again. Time and a browned outside alone do not prove it is cooked. Cook additional batches rather than piling up the basket. Move cooked chicken to a clean bowl; save lime and spring onion for assembly.','Put the already-seasoned chicken in a preheated air fryer at 200°C. Cook about 10–12 minutes, turning at 5 minutes.','Cut open several of the largest pieces with a clean knife: the centre should be steaming hot, with no pink meat and clear juices. If any check fails or you are unsure, cook longer and check again. Time and a browned outside alone do not prove it is cooked.',600,200,'{"hint":"Less time at the hob","facts":[["Preheat","200°C · about 5 min"],["Cook","10–12 min per batch"],["Turn","At 5 min"]],"checklist":["Preheat to 200°C. Use the seasoned chicken from step 5 without adding more seasoning.","Load one uncrowded layer, leaving excess liquid behind. Start the timer after loading.","Turn at 5 minutes. From 10 minutes, cut open the largest pieces and use all the checks below."],"methodNote":"The timing comes from an unbreaded chicken-bite recipe using the same approximate cube size. Our ginger-and-soy coating is an adaptation; the full method still needs kitchen testing.","adjustableTimer":false,"timerLabel":"Check chicken at 10 minutes","checkpointSeconds":300,"checkpointMessage":"Air fryer: shake or turn the chicken now, then continue cooking."}'::jsonb,'https://www.laurafuentes.com/air-fryer-chicken-bites/',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=B2co2uSknew'));
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='ginger-chicken'),'video','youtube','https://www.youtube.com/watch?v=hZsLAZMIFBQ','How to steam broccoli','Foods101withDeronda','Third-party platform embed; no download or editing permission obtained.','https://www.youtube.com/watch?v=hZsLAZMIFBQ','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),6,'Cook the vegetables','Use the broccoli and carrots already cut in step 2. Steam them together until tender, starting your check at 5 minutes.','Bring a little water to the boil under a steamer basket; the water must not touch the vegetables. Add the prepared broccoli and thin carrot slices, cover, and keep steam rising. Check from 5 minutes and allow roughly 5–7 minutes, longer if the carrot is still firm. Remove tender broccoli first if the carrots need longer. Keep water in the pot, lift the lid away from your face and drain off excess moisture. Do not put the cucumber, spring onion or lime in the steamer.','A fork should pass through a carrot slice and a broccoli stem with gentle resistance. Drain well so the rice bowl does not become watery.',300,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=hZsLAZMIFBQ'),0,null,'steam');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='ginger-chicken') and position=6),(select id from public.recipes where slug='ginger-chicken'),'steam','Steam','Bring a little water to the boil under a steamer basket; the water must not touch the vegetables. Add the prepared broccoli and thin carrot slices, cover, and keep steam rising. Check from 5 minutes and allow roughly 5–7 minutes, longer if the carrot is still firm. Remove tender broccoli first if the carrots need longer. Keep water in the pot, lift the lid away from your face and drain off excess moisture. Do not put the cucumber, spring onion or lime in the steamer.','Use the broccoli and carrots already cut in step 2. Steam them together until tender, starting your check at 5 minutes.','A fork should pass through a carrot slice and a broccoli stem with gentle resistance. Drain well so the rice bowl does not become watery.',300,null,'{"hint":"Basket and lid","facts":[["Method","Steam above water"],["Cook","About 5–7 min"],["Prep","Already done in step 2"]],"checklist":["Take the broccoli and carrots from step 2—no cutting again.","Steam over boiling water with a lid. Start the timer once steam is rising around the vegetables.","Check both vegetables; remove tender pieces first and drain well."],"methodNote":"Steam or boil: these vegetables are a separate side, so either method works with the same final bowl.","adjustableTimer":false,"timerLabel":"First vegetable check at 5 minutes"}'::jsonb,'https://www.loveandlemons.com/steamed-broccoli/',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='ginger-chicken') and url='https://www.youtube.com/watch?v=hZsLAZMIFBQ'));
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='ginger-chicken') and position=6),(select id from public.recipes where slug='ginger-chicken'),'boil','Boil','Bring enough water to cover the vegetables to the boil. Add the thin carrot slices from step 2. Once the water returns to the boil, start the timer. After 2 minutes add the prepared broccoli; continue for about 4–5 minutes after the water returns to a gentle boil. Check both vegetables and remove tender pieces first if needed. Drain in a colander, away from your face. Keep cucumber, spring onion and lime raw for assembly. Size and batch volume change the time, so use the fork check.','Boil the prepared carrot slices for 2 minutes, add the broccoli, then cook for another 4–5 minutes and drain.','A fork should pass through a carrot slice and a broccoli stem with gentle resistance. Drain well so the rice bowl does not become watery.',420,null,'{"hint":"Just a pot and colander","facts":[["Carrots first","2 min"],["Then add broccoli","Another 4–5 min"],["Finish","Drain well"]],"checklist":["Add carrot slices to boiling water. Start the timer when it returns to the boil.","At the 2-minute reminder, add broccoli. Boil another 4–5 minutes after the water returns to a gentle boil.","Fork-check a carrot slice and a broccoli stem, then drain."],"methodNote":"Steam or boil: these vegetables are a separate side, so either method works with the same final bowl.","adjustableTimer":false,"timerLabel":"Check vegetables (about 7 minutes total)","checkpointSeconds":120,"checkpointMessage":"Vegetables: add the prepared broccoli now. Cook for another 4–5 minutes after the water returns to a gentle boil.","mediaGap":"A boiling-only technique clip is still to be reviewed. Follow the three actions above for this method.","gapTitle":"Boil the prepared vegetables"}'::jsonb,'https://www.bbcgoodfood.com/howto/guide/how-to-cook-broccoli',null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='ginger-chicken'),7,'Build and portion your bowls','Divide rice, cooked ginger chicken, broccoli and carrots between your portions. Finish with the prepared cucumber, spring onion and lime.','Check the rice is tender and fluff it. Divide rice, cooked chicken and its cooked pan juices (if using the pan), broccoli and carrots evenly between your selected number of portions. Add the cucumber and spring onion from step 2 and squeeze over lime to taste. For meal prep, keep these cold toppings separate until serving. Do not reuse liquid left in the raw-chicken bowl. Follow the cooling and storage guidance promptly.','One bowl containing all six components: rice, ginger chicken, broccoli, carrots, cucumber and fresh toppings. Pan chicken is slightly saucier; air-fried chicken is drier.',0,null,0,null,null);
insert into public.nutrition_estimates(recipe_id,kcal,protein_g,carbs_g,fat_g,fibre_g,method) values ((select id from public.recipes where slug='ginger-chicken'),515,43,49,16,7,'Illustrative manual estimates. Not a validated ingredient-level calculation.');
insert into public.prep_guidance(recipe_id,portioning,cooling,storage,reheating,source_url) values ((select id from public.recipes where slug='ginger-chicken'),'Divide the cooked rice, chicken, broccoli and carrots into portions. Pack cucumber, spring onion and lime separately and add after reheating. Freeze cooked portions intended for later promptly after cooling; prepare fresh cold toppings when serving.','Refrigerate or freeze within 2 hours. Cool rice promptly.','Refrigerate at 4°C or below. Plan to eat the next day; freeze later portions promptly.','Reheat cooked portions until steaming hot all the way through. Keep cold salad separate.','https://www.sfa.gov.sg/food-safety-tips/safe-food-practices/food-safety-tips');
