insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),0,'Choose your rice','Keep the ready-cooked rice pouch unopened until step 7.','Keep the ready-cooked rice pouch unopened until step 7. Cooking for later? Store salmon and vegetables separately; heat rice only when serving.','Ready-cooked rice, ready to heat.',0,null,0,null,'pouch');
