insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=0),(select id from public.recipes where slug='sesame-salmon'),'chilled','Chilled rice','Use rice cooled promptly, refrigerated and cooked within the last 24 hours. It must not have been reheated. Keep chilled until step 7. Reheat once and eat now.','Use rice cooled promptly, refrigerated and cooked within the last 24 hours. It must not have been reheated.','If storage history is unknown, cook fresh rice.',0,null,'{"hint":"Eat this meal now","adjustableTimer":false}'::jsonb,'https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker',null);
