insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=0),(select id from public.recipes where slug='sesame-salmon'),'stovetop','Fresh rice','Start with about 70 g dry rice per portion. Rinse; follow the packet’s water ratio and cooking time. Weigh out 210 g cooked rice per portion. Cool any extra promptly. Allow about 55–65 minutes for the meal; cook the salmon near the end.','Start with about 70 g dry rice per portion. Rinse; follow the packet’s water ratio and cooking time.','Tender grains; no hard centre.',2700,null,'{"hint":"Allow 55–65 minutes","adjustableTimer":true,"timerLabel":"Set your packet cooking time"}'::jsonb,'https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=LzsSQmbALSo'));
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=0),(select id from public.recipes where slug='sesame-salmon'),'rice-cooker','Rice cooker','Rinse rice. Use your cooker’s cup, brown-rice water guide and minimum batch size. Run the full cycle and rest. Fluff; weigh out 210 g cooked rice per portion. Allow extra time for the cooker cycle. Cool spare rice promptly.','Rinse rice. Use your cooker’s cup, brown-rice water guide and minimum batch size.','Tender grains after the full cycle and rest.',0,null,'{"hint":"Hands-off cooking","facts":[["Setting","Brown Rice"],["Temperature","Automatic"],["Time","Your cooker’s full cycle"]],"adjustableTimer":false,"mediaGap":"A matching rice-cooker video is still to be added. Zojirushi’s linked guide has step-by-step photographs; follow your own model’s manual for settings.","gapTitle":"Set the rice cooking"}'::jsonb,'https://zojirushi.sg/recipes/brown-rice/',null);
