insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),1,'Prepare the vegetables','Wash produce. Cut broccoli into 3 cm florets and carrots into 3 mm slices.','Wash produce. Cut broccoli into 3 cm florets and carrots into 3 mm slices. Slice cucumber into half-moons; keep it chilled separately.','Even broccoli and carrot pieces; cucumber kept separate.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=CRYQeHVkh8E'),0,null,null);
