insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),2,'Mix the ginger dressing','Peel ginger with a spoon, then finely grate it. Keep fingertips away from the grater.','Peel ginger with a spoon, then finely grate it. Keep fingertips away from the grater. Mix with all the soy sauce and rice vinegar. Keep this dressing away from raw fish.','A thin dressing with fine ginger shreds.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=v908vjRX8Gc'),0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='sesame-salmon'),'video','youtube','https://www.youtube.com/watch?v=j1Q6xfl-MLw','Find and remove salmon pin bones','Howcast / Brendan McDermott','Third-party platform embed; no download or editing permission obtained.','https://howcast.com/videos/509009-how-to-remove-pin-bones-from-salmon-fish-filleting/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),3,'Prepare the salmon','Keep the fillets whole and skin-on. Pat dry with kitchen paper; feel along the flesh for pin bones.','Keep the fillets whole and skin-on. Pat dry with kitchen paper; feel along the flesh for pin bones. Pull any bones out with clean fish tweezers, in the direction they point. Brush with the measured oil. Keep dressing and sesame for serving. Wash hands and clean raw-fish tools.','Whole fillets, no remaining pin bones, lightly coated with oil.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=j1Q6xfl-MLw'),0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='sesame-salmon'),'video','youtube','https://www.youtube.com/watch?v=gbeZAN0mOi8','Air fryer salmon','Lisa Bryan / Downshiftology','Third-party platform embed; no download or editing permission obtained.','https://downshiftology.com/recipes/air-fryer-salmon/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),4,'Cook the salmon','Set the air fryer to 200°C; preheat only if your manual requires it.','Set the air fryer to 200°C; preheat only if your manual requires it. Place fillets skin-side down, spaced apart. Cook 8–10 minutes; start checking at 8 minutes. While it cooks, continue with vegetables and rice. Use more batches if crowded.','Thickest part: steaming hot, opaque and flakes easily. If translucent or cool, cook longer and check again.',480,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=gbeZAN0mOi8'),0,null,'air-fryer');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=4),(select id from public.recipes where slug='sesame-salmon'),'air-fryer','Air fryer','Set the air fryer to 200°C; preheat only if your manual requires it. Place fillets skin-side down, spaced apart. Cook 8–10 minutes; start checking at 8 minutes. While it cooks, continue with vegetables and rice. Use more batches if crowded.','Set the air fryer to 200°C; preheat only if your manual requires it.','Thickest part: steaming hot, opaque and flakes easily. If translucent or cool, cook longer and check again.',480,null,'{"hint":"200°C · 8–10 min","adjustableTimer":false,"timerLabel":"First check at 8 minutes"}'::jsonb,'https://downshiftology.com/recipes/air-fryer-salmon/',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=gbeZAN0mOi8'));
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=4),(select id from public.recipes where slug='sesame-salmon'),'oven','Oven','Heat oven to 180°C (160°C fan). Place oiled salmon skin-side down on a lined tray. Bake 10–15 minutes; thicker fillets may need longer. Check from 10 minutes. Cook vegetables and heat rice meanwhile. Allow about 30 minutes for the full bowl.','Heat oven to 180°C (160°C fan). Place oiled salmon skin-side down on a lined tray.','Thickest part: steaming hot, opaque and flakes easily. If translucent or cool, cook longer and check again.',600,null,'{"hint":"180°C / 160°C fan","adjustableTimer":false,"timerLabel":"First check at 10 minutes"}'::jsonb,'https://www.bbcgoodfood.com/howto/guide/how-cook-salmon',null);
