insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),5,'Cook the vegetables','Use broccoli and carrots already cut in step 2. Put in a basket above boiling water; cover.','Use broccoli and carrots already cut in step 2. Put in a basket above boiling water; cover. Steam 5–7 minutes; check from 5 minutes. Remove tender pieces first and drain. Keep water in the pot. Open the lid away from your face.','A fork enters carrot and broccoli stems with gentle resistance.',300,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=hZsLAZMIFBQ'),0,null,'steam');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=5),(select id from public.recipes where slug='sesame-salmon'),'steam','Steam','Use broccoli and carrots already cut in step 2. Put in a basket above boiling water; cover. Steam 5–7 minutes; check from 5 minutes. Remove tender pieces first and drain. Keep water in the pot. Open the lid away from your face.','Use broccoli and carrots already cut in step 2. Put in a basket above boiling water; cover.','A fork enters carrot and broccoli stems with gentle resistance.',300,null,'{"hint":"5–7 min","adjustableTimer":false,"timerLabel":"First check at 5 minutes"}'::jsonb,'https://www.loveandlemons.com/steamed-broccoli/',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='sesame-salmon') and url='https://www.youtube.com/watch?v=hZsLAZMIFBQ'));
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=5),(select id from public.recipes where slug='sesame-salmon'),'boil','Boil','Add prepared carrots to boiling water. Once boiling again, cook 2 minutes. Add broccoli. Once gently boiling again, cook 4–5 minutes. Fork-check both vegetables, then drain carefully.','Add prepared carrots to boiling water. Once boiling again, cook 2 minutes.','A fork enters carrot and broccoli stems with gentle resistance.',420,null,'{"hint":"Just a pot and colander","facts":[["Carrots first","2 min"],["Then add broccoli","Another 4–5 min"],["Finish","Drain well"]],"adjustableTimer":false,"timerLabel":"Check vegetables (about 7 minutes total)","checkpointSeconds":120,"checkpointMessage":"Vegetables: add the prepared broccoli now. Cook for another 4–5 minutes after the water returns to a gentle boil.","mediaGap":"A boiling-only technique clip is still to be reviewed. Follow the three actions above for this method.","gapTitle":"Boil the prepared vegetables"}'::jsonb,'https://www.bbcgoodfood.com/howto/guide/how-to-cook-broccoli',null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),6,'Heat the rice','Heat ready-cooked pouch rice following its packet. Serve freshly cooked rice as it is.','Heat ready-cooked pouch rice following its packet. Serve freshly cooked rice as it is. For chilled rice: cover with a vent and a splash of water. Microwave in short bursts, stirring until steaming throughout. Reheat rice once only and eat now. For meal prep, leave pouches unopened and follow Meal prep.','Steaming-hot rice throughout; no cold pockets.',0,null,0,null,'microwave');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=6),(select id from public.recipes where slug='sesame-salmon'),'microwave','Microwave','Heat ready-cooked pouch rice following its packet. Serve freshly cooked rice as it is. For chilled rice: cover with a vent and a splash of water. Microwave in short bursts, stirring until steaming throughout. Reheat rice once only and eat now. For meal prep, leave pouches unopened and follow Meal prep.','Heat ready-cooked pouch rice following its packet. Serve freshly cooked rice as it is.','Steaming-hot rice throughout; no cold pockets.',0,null,'{"hint":"Follow the rice packet","adjustableTimer":false}'::jsonb,'https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker',null);
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='sesame-salmon') and position=6),(select id from public.recipes where slug='sesame-salmon'),'stovetop','Stovetop','For a pouch, follow its stovetop directions. For chilled rice, add a splash of water to a saucepan and cover. Warm gently, stirring until steaming throughout. Freshly cooked hot rice needs no reheating. Reheat rice once only and eat now. For meal prep, leave pouches unopened and follow Meal prep.','For a pouch, follow its stovetop directions. For chilled rice, add a splash of water to a saucepan and cover.','Steaming-hot rice throughout; no cold pockets.',0,null,'{"hint":"Covered saucepan","adjustableTimer":false}'::jsonb,'https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker',null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='sesame-salmon'),7,'Build your bowls','Divide rice, salmon, broccoli and carrots between bowls. Add cucumber.','Divide rice, salmon, broccoli and carrots between bowls. Add cucumber. Drizzle with the clean ginger dressing and sprinkle over all the sesame. Eating later? Keep components separate and follow Meal prep.','Salmon over rice, colourful vegetables alongside, sesame on top.',0,null,0,null,null);
