insert into public.prep_guidance(recipe_id,portioning,cooling,storage,reheating,source_url) values ((select id from public.recipes where slug='sesame-salmon'),'Store salmon and cooked vegetables separately from cucumber and dressing. Keep rice pouches unopened until serving, or cook fresh rice and cool promptly. Do not store reheated rice for another meal.','Refrigerate or freeze within 2 hours. Cool rice promptly.','Refrigerate at 4°C or below. Plan to eat the next day; freeze later portions promptly.','Reheat cooked portions until steaming hot all the way through. Keep cold salad separate.','https://www.sfa.gov.sg/food-safety-tips/safe-food-practices/food-safety-tips');
