insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),0,'Choose your rice route','Have cooked rice ready, or start a fresh batch before preparing the filling.','For each portion, use 75 g cooked brown rice, approximately the yield from 25 g dry rice. Do not add both cooked and dry rice. Actual yield varies; weigh the cooked amount you need. For a new batch, start it first and time the filling for the final 15 minutes.','Cooked rice is tender through the centre, with separate grains.',2700,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and url='https://www.youtube.com/watch?v=LzsSQmbALSo'),0,null,'cooked-rice');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=0),(select id from public.recipes where slug='chicken-cheese-burrito'),'cooked-rice','Already cooked','Use home-cooked rice that was cooled promptly and refrigerated, within 24 hours of cooking, and has not already been reheated. For future meal prep, choose fresh rice instead: this quick route is for eating immediately after heating.','Keep safely chilled cooked rice in the fridge until step 5. Reheat it once, just before filling.','The rice has a known safe storage history. If you do not know how it was stored, cook a fresh batch.',0,null,'{"hint":"Quick route · eat this meal now","facts":[["Total meal time","About 30 min"],["Rice","75 g cooked / portion"]],"checklist":["Keep the measured cooked rice chilled while making the filling.","Use step 5 to reheat it once. Do not cool and store that reheated rice for another meal."],"methodNote":"The 30-minute estimate assumes rice is already cooked. Fresh rice and multiple cooking batches take longer.","adjustableTimer":false,"timerLabel":"Rice reminder","mediaGap":"No video needed for this choice. The storage history matters more than appearance.","gapTitle":"Use rice you already cooked"}'::jsonb,'https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker',null);
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=0),(select id from public.recipes where slug='chicken-cheese-burrito'),'stovetop','Stovetop','Cook a practical batch according to the packet, especially if your pan needs more than this small amount. Weigh out 75 g cooked rice per portion. Cool and store any extra promptly. Cook the filling near the end of the rice cooking time.','Use 25 g dry brown rice per portion; follow the packet’s water ratio and cooking time.','Tender grains with no hard centre. The demo uses its own rice ratio; follow your packet for yours.',2700,null,'{"hint":"Start from dry rice","facts":[["Heat","Gentle simmer"],["Time","Follow your rice packet"]],"checklist":["Use the packet’s ratio and time. A covered gentle simmer is typical.","Aim for 75 g cooked rice per portion; extra batch rice is not extra burrito filling."],"methodNote":"Fresh rice increases total meal time. The cost estimate covers only the rice allocated to these burritos.","adjustableTimer":true,"timerLabel":"Rice reminder"}'::jsonb,'https://learntocook.com/rice/how-to-cook-brown-rice/',(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and url='https://www.youtube.com/watch?v=LzsSQmbALSo'));
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=0),(select id from public.recipes where slug='chicken-cheese-burrito'),'rice-cooker','Rice cooker','Follow your model’s brown-rice instructions and minimum batch. Aim for 75 g cooked rice per portion; the approximate dry equivalent is 25 g per portion. Cook a larger batch if necessary, measure the required cooked rice, and promptly cool any extra. A rice-cooker cycle may take longer than an hour.','Cook brown rice using your cooker’s own water markings and minimum batch size.','The cooker has finished its full cycle and any instructed rest. Grains should be tender through the centre.',0,null,'{"hint":"Hands-off cooking","facts":[["Setting","Brown Rice"],["Temperature","Automatic"],["Time","Your cooker’s full cycle"]],"checklist":["Use the cooker’s own cup and brown-rice water guide; check its minimum batch size.","Select Brown Rice and complete the ingredient prep while it cooks.","Let the whole cycle and any instructed rest finish, then fluff."],"methodNote":"Use your model’s complete cycle. Costs cover the dry equivalent used in this recipe, not extra rice cooked to meet a minimum batch.","adjustableTimer":false,"timerLabel":"Rice reminder","mediaGap":"A matching rice-cooker video is still to be added. Zojirushi’s linked guide has step-by-step photographs; follow your own model’s manual for settings.","gapTitle":"Set the rice cooking"}'::jsonb,'https://zojirushi.sg/recipes/brown-rice/',null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='chicken-cheese-burrito'),'video','youtube','https://www.youtube.com/watch?v=Z__TQweFH2E','How to cut a bell pepper','Nick’s Kitchen','Third-party platform embed; no download or editing permission obtained.','https://www.youtube.com/watch?v=Z__TQweFH2E','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),1,'Prepare vegetables & cheese','Cut the pepper and onion once, before handling raw chicken. Keep the cheese separate.','Wash the pepper, remove its stalk and seeds, and cut into strips around 5 mm wide. Peel the onion, halve it and place the flat side on the board; slice about 5 mm thick. Halve long vegetable strips to make the filling easier to bite. Grate the cheddar if it is not already shredded. Refrigerate the cheese until filling time.','Similar-width vegetable strips, short enough to fit inside the wrap. Cheese is grated, not mixed into the raw filling.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and url='https://www.youtube.com/watch?v=Z__TQweFH2E'),0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='chicken-cheese-burrito'),'video','youtube','https://www.youtube.com/watch?v=-l3TxkEldPs','Cut chicken into strips and pieces','MOMables / Laura Fuentes','Third-party platform embed; no download or editing permission obtained.','https://www.laurafuentes.com/cut-chicken-breasts/','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),2,'Slice & season the chicken','Slice chicken into 1 cm-thick strips, then mix it with the prepared vegetables, oil, paprika and cumin once.','Use a separate board for raw chicken. Cut across the grain into strips about 1 cm thick and 3–4 cm long. Add the chicken to the vegetable bowl with all the measured oil, paprika and cumin. Mix to coat everything evenly. Wash hands and clean the knife, board and surfaces before touching wraps or cheese. Do not rinse raw chicken.','Chicken and vegetables have a light, even spice coating. The cheese, rice, salsa and wraps are still separate.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and url='https://www.youtube.com/watch?v=-l3TxkEldPs'),0,null,null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),3,'Cook the chicken filling','Cook the already-seasoned chicken and vegetables in a hot non-stick pan, stirring and turning regularly.','Heat a large non-stick frying pan over medium-high heat. Spread the seasoned mixture out and cook for about 8–12 minutes, turning often. Work in batches if it is crowded. Lower the heat if the spices scorch. Check the largest chicken strips before removing the filling; the timer is a first-check reminder.','Cut open several thick chicken strips: the centre should be steaming hot, with no pink meat and clear juices. Cook longer if uncertain. Vegetables should be tender with some browned edges; avoid watery filling.',480,null,0,null,'pan');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=3),(select id from public.recipes where slug='chicken-cheese-burrito'),'pan','Pan','Heat a large non-stick frying pan over medium-high heat. Spread the seasoned mixture out and cook for about 8–12 minutes, turning often. Work in batches if it is crowded. Lower the heat if the spices scorch. Check the largest chicken strips before removing the filling; the timer is a first-check reminder.','Cook the already-seasoned chicken and vegetables in a hot non-stick pan, stirring and turning regularly.','Cut open several thick chicken strips: the centre should be steaming hot, with no pink meat and clear juices. Cook longer if uncertain. Vegetables should be tender with some browned edges; avoid watery filling.',480,null,'{"hint":"First check at 8 min","facts":[["Heat","Medium-high"],["Time","About 8–12 min / batch"]],"checklist":["Use the whole mixture from step 3; no more oil or seasoning is required.","Turn regularly and avoid crowding.","Check chicken through the centre, then move to a clean bowl."],"adjustableTimer":false,"timerLabel":"First check at 8 minutes","mediaGap":"A cooking-only pan clip is still to be reviewed. Do not repeat cutting or add a second batch of seasoning.","gapTitle":"Cook the prepared filling"}'::jsonb,'https://www.bbcgoodfoodme.com/recipes/easy-chicken-fajitas/',null);
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=3),(select id from public.recipes where slug='chicken-cheese-burrito'),'air-fryer','Air fryer','Use the mixture from step 3 without seasoning again. Cook in batches if needed. At about 5 and 10 minutes, use tongs to turn and redistribute the strips. Check several thick chicken pieces at 15 minutes and continue cooking if needed. Keep uncooked batches refrigerated while waiting. Timing varies by appliance and load.','Preheat to 200°C. Spread the already-seasoned filling in a shallow, uncrowded layer and air-fry for about 15 minutes.','Cut open several thick chicken strips: the centre should be steaming hot, with no pink meat and clear juices. Cook longer if uncertain. Vegetables should be tender with some browned edges; avoid watery filling.',900,200,'{"hint":"200°C · about 15 min","facts":[["Temperature","200°C"],["Time","About 15 min / batch"],["Turn","At 5 and 10 min"]],"checklist":["Preheat to 200°C; allow space for air to circulate.","Turn after about 5 minutes, then again around 10 minutes.","At 15 minutes, check the thickest chicken strips; cook longer if any check fails."],"adjustableTimer":false,"timerLabel":"Filling reminder · check at 15 min","checkpointSeconds":300,"checkpointMessage":"Turn and redistribute the burrito filling now; repeat at about 10 minutes.","mediaGap":"A matching cooking-only air-fryer clip is still pending. Available full-recipe videos repeat preparation or use a different timing sequence, so they are not substituted here.","gapTitle":"Cook the prepared filling"}'::jsonb,'https://boredoflunch.com/recipes/air-fryer-chicken-fajitas/',null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),4,'Warm rice & soften the wraps','For eating now, heat chilled rice until steaming throughout and soften the wraps. Freshly cooked hot rice only needs fluffing.','Reheat only the rice you will eat now. In a microwave-safe covered container with a vent, add a small splash of water, heat in short bursts and stir between them until all the rice is steaming hot. Heat wraps separately according to their packet, just until flexible. Never microwave foil. For future meal prep, skip warming, filling and toasting: cool fresh filling and rice separately, then follow the Meal prep tab.','Rice is hot through the centre, without cold pockets. Wraps bend easily without cracking and remain soft.',0,null,0,null,'microwave');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=4),(select id from public.recipes where slug='chicken-cheese-burrito'),'microwave','Microwave','Reheat only the rice you will eat now. In a microwave-safe covered container with a vent, add a small splash of water, heat in short bursts and stir between them until all the rice is steaming hot. Heat wraps separately according to their packet, just until flexible. Never microwave foil. For future meal prep, skip warming, filling and toasting: cool fresh filling and rice separately, then follow the Meal prep tab.','For eating now, heat chilled rice until steaming throughout and soften the wraps. Freshly cooked hot rice only needs fluffing.','Rice is hot through the centre, without cold pockets. Wraps bend easily without cracking and remain soft.',0,null,'{"hint":"Short bursts · stir rice","facts":[["Rice","Reheat once only"],["Wraps","Warm until flexible"]],"checklist":["Use freshly hot rice as it is; reheat safely chilled rice once.","Warm only the wraps you will fill now.","For later meals, store components separately instead of heating and cooling them again."],"adjustableTimer":false,"mediaGap":"Follow your wrap packet and appliance instructions. An exact matching short video is still pending.","gapTitle":"Warm, flexible wraps"}'::jsonb,'https://www.bbcgoodfood.com/recipes/easy-chicken-burritos',null);
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=4),(select id from public.recipes where slug='chicken-cheese-burrito'),'pan','Stovetop','Use gentle heat for the covered rice and stir to remove cold spots. Freshly cooked hot rice does not need reheating. Warm each wrap briefly on both sides in a clean, dry pan, following its packet. Stop before it becomes crisp; it must bend for folding. Reheat rice only once, and eat immediately.','Warm chilled rice in a covered saucepan with a splash of water, stirring until steaming throughout. Soften wraps separately in a dry pan.','Rice is hot through the centre, without cold pockets. Wraps bend easily without cracking and remain soft.',0,null,'{"hint":"No microwave needed","facts":[["Rice","Reheat once only"],["Wraps","Warm until flexible"]],"checklist":["Heat chilled rice with a small splash of water, covered, stirring regularly.","Warm wraps in a separate dry pan until flexible, not crunchy.","Skip this reheating step for rice already hot from cooking."],"adjustableTimer":false,"mediaGap":"Follow your wrap packet and appliance instructions. An exact matching short video is still pending.","gapTitle":"Warm, flexible wraps"}'::jsonb,'https://www.bbcgoodfood.com/recipes/easy-chicken-burritos',null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),5,'Fill with chicken & cheese','Make two small burritos per portion. Divide the rice, cooked filling, cheese and salsa evenly between the wraps.','Keep the filling compact near the middle of each warm wrap, leaving clear space around its edges. Add rice, chicken and vegetables, cheddar and a small spoon of salsa. Use the measured salsa sparingly to avoid a wet seam. If your wrap cannot close comfortably, serve a little filling alongside rather than forcing it to split.','A compact strip of filling with enough bare tortilla on every side to fold over it.',0,null,0,null,null);
insert into public.media_assets(recipe_id,kind,provider,url,title,attribution,license,source_url,rights_basis,status) values ((select id from public.recipes where slug='chicken-cheese-burrito'),'video','youtube','https://www.youtube.com/watch?v=T5wRjcj60WI','How to wrap a burrito','Twisted','Third-party platform embed; no download or editing permission obtained.','https://www.youtube.com/watch?v=T5wRjcj60WI','platform_embed','pending');
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),6,'Fold, tuck & roll','Fold the sides inward, bring the near edge over the filling, tuck gently and roll away from you.','Hold the side folds in place as you roll. Use gentle pressure to keep the filling together without tearing the wrap. Rest it with the seam underneath. If it splits, remove some filling and try again with a fresh wrap, or eat it as an open wrap.','The ends are closed, the seam sits underneath, and the wrap holds together without a tear.',0,(select id from public.media_assets where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and url='https://www.youtube.com/watch?v=T5wRjcj60WI'),0,null,null);
insert into public.recipe_steps(recipe_id,position,title,short_instruction,instruction,visual_cue,timer_seconds,video_id,video_start_seconds,video_end_seconds,default_method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),7,'Toast lightly & take along','Optional: toast the filled burrito seam-side down in a dry pan for 1–2 minutes per side. Eat while freshly hot.','Use medium heat, turning gently once the seam holds. This step adds colour and softens the cheese; the chicken and rice must already be fully cooked and hot. Leave the burrito whole for easier eating on the go. If carrying it for later, use freshly cooked components that were cooled promptly, assemble cold, and keep chilled in an insulated bag with an ice pack. Foil alone does not keep food safely cold.','Light golden patches, a secure seam and softened cheese. Toasting is not a substitute for cooking the filling through.',60,null,0,null,'pan');
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=7),(select id from public.recipes where slug='chicken-cheese-burrito'),'pan','Toast in pan','Use medium heat, turning gently once the seam holds. This step adds colour and softens the cheese; the chicken and rice must already be fully cooked and hot. Leave the burrito whole for easier eating on the go. If carrying it for later, use freshly cooked components that were cooled promptly, assemble cold, and keep chilled in an insulated bag with an ice pack. Foil alone does not keep food safely cold.','Optional: toast the filled burrito seam-side down in a dry pan for 1–2 minutes per side. Eat while freshly hot.','Light golden patches, a secure seam and softened cheese. Toasting is not a substitute for cooking the filling through.',60,null,'{"hint":"Optional · 1–2 min / side","facts":[["Heat","Medium"],["Time","1–2 min / side"],["Purpose","Optional colour and softer cheese"]],"checklist":["Start with already hot, cooked filling.","Toast briefly, or skip this step for a soft wrap.","See Meal prep for cold transport and reheating."],"adjustableTimer":false,"timerLabel":"Check the first side after 1 minute","mediaGap":"A matching finishing clip is still pending. The folding demo in step 7 covers the key portable-meal technique.","gapTitle":"A wrap that holds together"}'::jsonb,'https://www.gov.uk/government/publications/food-safety-in-a-heatwave-advice-for-consumers/food-safety-in-a-heatwave-advice-for-consumers',null);
insert into public.recipe_step_methods(step_id,recipe_id,method_key,label,instruction,short_instruction,visual_cue,timer_seconds,temperature_c,ui_details,source_url,video_id) values ((select id from public.recipe_steps where recipe_id=(select id from public.recipes where slug='chicken-cheese-burrito') and position=7),(select id from public.recipes where slug='chicken-cheese-burrito'),'soft','Keep it soft','The filling must already be fully cooked and hot. Keep the folded burrito whole and support its lower half with food-safe wrapping for easy eating. For a later packed lunch, assemble from promptly chilled components and keep cold during transport.','Skip toasting. Rest the freshly filled burrito seam-side down, then eat immediately.','Light golden patches, a secure seam and softened cheese. Toasting is not a substitute for cooking the filling through.',0,null,'{"hint":"No extra cooking","facts":[["Finish","Soft wrap"],["Extra time","None"]],"checklist":["Check that the sides are tucked and seam is underneath.","Eat freshly hot, or follow the separate chilled meal-prep route."],"adjustableTimer":false,"timerLabel":"Check the first side after 1 minute","mediaGap":"A matching finishing clip is still pending. The folding demo in step 7 covers the key portable-meal technique.","gapTitle":"A wrap that holds together"}'::jsonb,'https://www.gov.uk/government/publications/food-safety-in-a-heatwave-advice-for-consumers/food-safety-in-a-heatwave-advice-for-consumers',null);
insert into public.nutrition_estimates(recipe_id,kcal,protein_g,carbs_g,fat_g,fibre_g,method) values ((select id from public.recipes where slug='chicken-cheese-burrito'),605,38,68,20,8,'Illustrative manual estimates. Not a validated ingredient-level calculation.');
insert into public.prep_guidance(recipe_id,portioning,cooling,storage,reheating,source_url) values ((select id from public.recipes where slug='chicken-cheese-burrito'),'For meal prep, use freshly cooked rice and filling. Store those separately from wraps, cheese and salsa; assemble when eating. The quick route with reheated rice is for immediate eating, not another cooling-and-reheating cycle.','Refrigerate or freeze within 2 hours. Cool rice promptly.','Refrigerate at 4°C or below. Plan to eat the next day; freeze later portions promptly.','Reheat cooked portions until steaming hot all the way through. Keep cold salad separate.','https://www.sfa.gov.sg/food-safety-tips/safe-food-practices/food-safety-tips');
